      dialog = 3,
      mask = "memory",
      music = "42_Echo_of_Fate_CUT",
      renwu = "npc",
      role1 = 234000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "From the age of seven, we'd all been subject to regular assessments. Your major, your career—even your partner—were all determined by the number attached to your name.",
