      renwu = "npc",
      role1 = 234000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "Those with high scores naturally climbed higher, reaping better opportunities, better housing, and better lives. And those with low scores? Even their basic freedoms came with a ceiling.",
