      music = "42_Echo_of_Fate_CUT",
      renwu = "npc",
      role1 = 234000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "For people like Lucien, whose score was at the pinnacle of the pyramid, everything was within reach, whether it was wealth or power.",
