    },
    [17] = {
      beijing = 1352,
      dialog = 3,
      music = "06_Love",
      renwu = "npc",
      ruchang = 0,
      sentence = "We looked out at the water under the setting sun. A vast stretch of crimson clouds swirled in the space between sea and sky, looking like some other, splendid world.",
