    },
    [18] = {
      beijing = 1352,
      dialog = 3,
      music = "06_Love",
      renwu = "npc",
      ruchang = 0,
      sentence = "The surface of the water was also tinged with golden red, and glistening waves crashed one after another against the shore, shattering into splashes of golden droplets.",
