      renwu = "npc",
      role1 = 302000,
      role2 = 302106,
      role3 = 302202,
      ruchang = 0,
      sentence = "When I think about how the sun is going to rise again tomorrow, and the sky is going to be the same azure blue, and the sea as boundless as ever, I know that all my worries don't mean a thing.",
