    },
    [29] = {
      beijing = 1352,
      dialog = 3,
      music = "06_Love",
      renwu = "npc",
      ruchang = 0,
      sentence = "This was a side of Kiro I never knew about. Probably no one would ever suspect that Kiro, more upbeat and sunny than anyone, would have a gloomy, lonely past.",
