      next = {32}
    },
    [32] = {
      beijing = 1352,
      dialog = 3,
      music = "06_Love",
      renwu = "npc",
      ruchang = 0,
      sentence = "I think so too. Always striving for a better tomorrow, what could be more beautiful than that?",
