      music = "57_Tanabata",
      renwu = "npc",
      sentence = [[
The three-footed Golden Crow lived in the sun.

At midnight it arose from bottom of the sea, emerging by the divine Mulberry Tree at dawn and roosting in the West at dusk.

Time ran on and the cycle began again.

One day it was raining and the Crow was flying along a riverbed. Suddenly it heard the sound of weeping and it flew down to take a look.

After several steps it saw a girl sheltering in the roots of a tree. Her clothes were soaked through, and the wind was howling.

Looking up, the girl saw the Crow and startled.

Thereafter they helped one another and neither was lonely again.]],
