    },
    [15] = {
      beijing = 2550,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "There were but a few planes on the spacious tarmac. I looked this way and that, but I didn't see the one that I usually trained in. Someone else was probably flying it.",
