    },
    [17] = {
      beijing = 2550,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "Having raised my spirits again, I got ready to leave—suddenly, in mid-air, a plane got ready to come in for a landing.",
